    'pamb.ci.badge': "La Côte d'Ivoire", 'pamb.ci.title':"Découvrir la Côte d'Ivoire",
    'pamb.ci.p1':   "La République de Côte d'Ivoire est un pays d'Afrique de l'Ouest, bordé au sud par le Golfe de Guinée. Première économie de l'Union Économique et Monétaire Ouest-Africaine (UEMOA), elle est le premier producteur mondial de cacao.",
    'pamb.ci.p2':   "Abidjan, capitale économique, est l'une des métropoles les plus dynamiques d'Afrique subsaharienne. Yamoussoukro est la capitale politique et administrative du pays.",
    'pamb.ci.stat.area':'Superficie', 'pamb.ci.stat.pop':'Population',
