    'pamb.org.badge': "L'Ambassade",
    'pamb.org.title': 'Organigramme',
    'pamb.org.p1':   "L'Ambassade et Représentation Permanente est organisée autour d'un Représentant Permanent et d'une équipe diplomatique spécialisée couvrant 9 pays d'Europe centrale.",
    'pamb.org.p2':   "La structure regroupe des Ministres Conseillers, une Directrice ONUDI, un Payeur, des Conseillers, des Premiers Secrétaires et le Personnel Administratif et Technique.",
