    'pamb.net.title':"Réseau diplomatique ivoirien dans le monde",
    'pamb.net.desc': "Ambassades, consulats généraux, missions et délégations permanentes répartis à travers le monde entier.",
    'pamb.net.amb':  'Ambassades',
    'pamb.net.cg':   'Consulats généraux',
    'pamb.net.mis':  'Missions & délégations',
