    'pamb.ci.badge': 'Côte d\'Ivoire', 'pamb.ci.title':'Côte d\'Ivoire entdecken',
    'pamb.ci.p1':   "Die Republik Côte d'Ivoire ist ein westafrikanischer Staat, der im Süden an den Golf von Guinea grenzt. Als größte Volkswirtschaft der Westafrikanischen Wirtschafts- und Währungsunion (UEMOA) ist sie der weltgrößte Kakaoproduzent.",
    'pamb.ci.p2':   "Abidjan, die Wirtschaftshauptstadt, ist eine der dynamischsten Metropolen Subsahara-Afrikas. Yamoussoukro ist die politische und administrative Hauptstadt des Landes.",
    'pamb.ci.stat.area':'Fläche', 'pamb.ci.stat.pop':'Bevölkerung',
