    'pamb.org.badge': 'Die Botschaft',
    'pamb.org.title': 'Organigramm',
    'pamb.org.p1':   'Die Botschaft und Ständige Vertretung ist um einen Ständigen Vertreter und ein spezialisiertes diplomatisches Team organisiert, das 9 mitteleuropäische Länder abdeckt.',
    'pamb.org.p2':   'Die Struktur umfasst Ministerberater, eine UNIDO-Direktorin, einen Zahlmeister, Berater, Erste Sekretäre und das Verwaltungs- und Technische Personal.',
    'pamb.org.btn':  'Organigramm ansehen →',
