    'net.filter.all':'Alle Posten','net.filter.circ':'Wahlkreise','net.filter.arcs':'Verbindungen ab Abidjan',
    'net.search.ph':'Stadt oder Land suchen…','net.hint':'Klicken Sie auf einen Punkt auf der Karte oder wählen Sie unten einen Posten aus, um Details anzuzeigen.','net.close':'Weltansicht',
    'net.footer':'Botschaft = bilaterale Vertretung bei einem Staat · Generalkonsulat = Konsularposten für einen Amtsbezirk · Ständige Mission = Vertretung bei einer internationalen Organisation.',
    'badge.ci':'Côte d\'Ivoire', 'ci.title':'Côte d\'Ivoire entdecken',
    'ci.republic':"Republik Côte d'Ivoire",
    'ci.area':'Fläche', 'ci.pop':'Bevölkerung',
    'ci.indep':'Unabhängigkeit', 'ci.indep.val':'7. August 1960', 'ci.capital':'Hauptstadt',
    'pamb.mis.p1':   'Die Botschaft der Republik Côte d\'Ivoire in Österreich ist die offizielle diplomatische Vertretung von Côte d\'Ivoire in Wien. Sie verteidigt die ivorischen Interessen, fördert bilaterale Beziehungen und schützt ihre Staatsangehörigen.',
    'pamb.mis.p2':   'Gegründet gemäß dem Wiener Übereinkommen über diplomatische Beziehungen von 1961, erfüllt die Botschaft eine doppelte Mission: diplomatisch (Vertretung des Staates beim Gastland) und konsular (Unterstützung ivorischer Staatsangehöriger in der Jurisdiktion).',
    'pamb.mis.p3':   'Im Rahmen ihrer territorialen Zuständigkeit deckt die Botschaft 9 Länder ab: Österreich, Ungarn, Slowenien, Slowakei, Kroatien, Serbien, Rumänien und Bosnien-Herzegowina.',
    'pamb.stat.countries':'Länder im diplomatischen Amtsbereich', 'pamb.stat.conv':'Wiener Konvention', 'pamb.stat.ci':'Côte d\'Ivoire', 'pamb.stat.host':'Gastgeberland',
    'pamb.amb.title':"Außerordentlicher und bevollmächtigter Botschafter der Republik Côte d'Ivoire in Österreich",
    'pamb.amb.p1':   'Seine Exzellenz Herr Cissé Yacouba ist bei der Republik Österreich als Außerordentlicher und Bevollmächtigter Botschafter der Republik Côte d\'Ivoire akkreditiert. Er ist auch bei Ungarn, Slowenien, der Slowakei, Kroatien, Serbien, Rumänien und Bosnien-Herzegowina akkreditiert.',
    'pamb.amb.p2':   'Mit einer langen diplomatischen Karriere im Dienst von Côte d\'Ivoire vertritt Seine Exzellenz Herr Cissé Yacouba die Interessen der Ivorischen Republik, fördert bilaterale und multilaterale Beziehungen und koordiniert alle Dienste der Botschaft.',
    'pcon.addr.official':'📍 Geografische Adresse',
    'pcon.table.window':'Konsularsschalter',
