    'dl.badge':      'Official Forms',
    'dl.h1':         'Downloadable Forms',
    'dl.desc':       'Download all official embassy forms for free. Print, fill out, and bring them to your appointment.',
    'dl.cat.passport':'Passport & Identity',
    'dl.cat.visa':   'Visa',
    'dl.cat.civil':  'Civil Status',
