    'dl.info.title': 'Important information',
    'dl.info.text':  'Forms must be printed, completed and signed before your appointment. All payments are made exclusively online.',
    'dl.f01.eyebrow':'Passport', 'dl.f01.title':'Passport application form', 'dl.f01.sub':'Ordinary / biometric passport abroad', 'dl.f01.desc':'Official form issued by the Ministry of Security. To be completed and signed before your consular appointment. Attach the required supporting documents.', 'dl.f01.size':'PDF · 68 KB',
    'dl.f02.eyebrow':'Registration', 'dl.f02.title':'Consular registration form', 'dl.f02.sub':'Registration in the roll of Ivorians abroad', 'dl.f02.desc':'Mandatory for all Ivorian nationals residing in Austria. Registration facilitates access to consular services and protects your rights abroad.', 'dl.f02.size':'PDF · 124 KB',
    'dl.f03.eyebrow':'Minor', 'dl.f03.title':'Parental authorisation', 'dl.f03.sub':"Authorisation for a minor's passport and/or birth certificate", 'dl.f03.desc':'Authorisation issued by the parent(s) for the issuance of a passport or birth certificate for a minor child. A legalised signature is required.', 'dl.f03.size':'PDF · 100 KB',
    'dl.f04.eyebrow':'Visa', 'dl.f04.title':'Visa application form', 'dl.f04.sub':'Ordinary, courtesy or diplomatic visa', 'dl.f04.desc':"Form to be used for any application for an entry visa to Côte d'Ivoire. All mandatory fields must be completed. A recent passport photo is required.", 'dl.f04.size':'PDF · 125 KB',
    'dl.f05.eyebrow':'Civil status', 'dl.f05.title':'Transcription of a birth certificate', 'dl.f05.sub':'Children born abroad to Ivorian parents', 'dl.f05.desc':'Form used to register a foreign birth certificate in the Ivorian civil status registers. Mandatory for obtaining nationality and a passport.', 'dl.f05.size':'PDF · 131 KB',
