    'dl.f02.eyebrow':'Regisztráció','dl.f02.title':'Konzuli regisztrációs formanyomtatvány','dl.f02.sub':'Bejegyzés a külföldön élő elefántcsontpartiak nyilvántartásába','dl.f02.desc':'Kötelező minden Ausztriában lakó elefántcsontparti állampolgár számára. A regisztráció megkönnyíti a konzuli szolgáltatások igénybevételét és védi jogait külföldön.','dl.f02.size':'PDF · 124 KB',
