    'dl.f05.eyebrow':'Anyakönyvi ügyek','dl.f05.title':'Születési anyakönyvi kivonat átírása','dl.f05.sub':'Külföldön született, elefántcsontparti szülők gyermekei','dl.f05.desc':'A külföldi születési anyakönyvi kivonat elefántcsontparti anyakönyvi nyilvántartásba történő bejegyzésére szolgáló formanyomtatvány. Kötelező az állampolgárság és az útlevél megszerzéséhez.','dl.f05.size':'PDF · 131 KB',
    'dl.f06.eyebrow':'Meghatalmazás','dl.f06.title':'Konzuli meghatalmazás','dl.f06.sub':'Megbízás harmadik fél nevében történő eljárásra','dl.f06.desc':'Lehetővé teszi egy kijelölt személy számára, hogy az Ön nevében ügyintézést végezzen a nagykövetségen vagy Elefántcsontpart területén.','dl.f06.size':'PDF · 89 KB',
    'dl.f07.eyebrow':'Hitelesítés','dl.f07.title':'Hitelesítési kérelem','dl.f07.sub':'Közigazgatási vagy közjegyzői dokumentumok hitelesítése','dl.f07.desc':'Elefántcsontparti vagy külföldi dokumentumok hitelesítésére szolgáló formanyomtatvány, amelyeket Elefántcsontparton vagy harmadik országban kívánnak felhasználni. Alkalmazható közjegyzői, közigazgatási és kereskedelmi okiratokra.','dl.f07.size':'PDF · 121 KB',
