    'ann.h1':'Információk és közlemények','ann.desc':'Itt találja a Bécsi Elefántcsontparti Nagykövetség összes hivatalos tájékoztatóját, fontos értesítését és közleményét.',
    'ann.pinned.label':'Kiemelt — Sürgős','ann.pinned.title':'Rendkívüli zárva tartás — Elefántcsontpart nemzeti ünnepe','ann.pinned.desc':'Az Elefántcsontparti Nagykövetség Bécsben <strong>2026. augusztus 7-én, pénteken zárva tart</strong> az Elefántcsontparti Köztársaság nemzeti ünnepe (a függetlenség 66. évfordulója) alkalmából. A szolgáltatások 2026. augusztus 10-én, hétfőn 09.30-kor folytatódnak rendben.','ann.pinned.date':'Közzétéve: 2026. május 25.',
    'ann.filter.all':'Összes','ann.filter.urgent':'Sürgős','ann.filter.admin':'Adminisztratív','ann.filter.event':'Események','ann.filter.communique':'Közlemények',
