    'pamb.h1':'Elefántcsontpart Nagykövetsége','pamb.desc':'Az Elefántcsontparti Köztársaság hivatalos képviselete Ausztriában, Bécsből, amely biztosítja a diplomáciai kapcsolatokat és a konzuli szolgáltatásokat Közép-Európa 9 országa számára.',
    'pamb.mis.badge':'Küldetésünk','pamb.mis.title':'Diplomáciai és konzuli küldetés',
    'pamb.pays.badge':'Illetékesség','pamb.pays.title':'Diplomáciai körzet','pamb.pays.sub':'Az Elefántcsontparti Nagykövetség Bécsben az alábbi 9 ország diplomáciai körzetét fedi le.',
