    'pamb.ci.badge':'Elefántcsontpart','pamb.ci.title':'Fedezze fel Elefántcsontpartot',
    'pamb.ci.p1':'Az Elefántcsontparti Köztársaság nyugat-afrikai ország, délen a Guineai-öböllel határos. A Nyugat-afrikai Gazdasági és Monetáris Unió (UEMOA) legnagyobb gazdasága, és a világ első számú kakaótermelője.',
    'pamb.ci.p2':'Abidjan, a gazdasági főváros, Fekete-Afrika egyik legdinamikusabb metropolisza. Yamoussoukro az ország politikai és közigazgatási fővárosa.',
    'pamb.ci.stat.area':'Terület','pamb.ci.stat.pop':'Népesség','pamb.ci.stat.lang':'Hivatalos nyelv','pamb.ci.stat.lang.val':'Francia','pamb.ci.stat.currency':'Pénznem','pamb.ci.stat.indep':'Függetlenség','pamb.ci.stat.indep.val':'1960. augusztus 7.','pamb.ci.stat.capital':'Politikai főváros',
    'pamb.ci.republic':'Elefántcsontparti Köztársaság',
    'pamb.org.badge':'A Nagykövetség','pamb.org.title':'Szervezeti felépítés',
    'pamb.org.p1':'A Nagykövetség és Állandó Képviselet egy Állandó Képviselő és egy szakosított diplomáciai csapat köré szerveződik, amely Közép-Európa 9 országát fedi le.',
    'pamb.org.p2':'A struktúra magában foglalja a miniszteri tanácsosokat, egy UNIDO igazgatónőt, egy pénztárost, tanácsosokat, első titkárokat és az adminisztratív és technikai személyzetet.',
