    'pamb.net.amb':'Nagykövetségek','pamb.net.cg':'Főkonzulátusok','pamb.net.mis':'Missziók és delegációk','pamb.net.circ':'Illetékességi körzetek','pamb.net.villes':'Városok','pamb.net.pays':'Fogadó országok',
