    'net.search.ph':'Keressen várost, országot…','net.hint':'Válasszon egy pontot a térképen, vagy egy posztot az alábbi listából a részletek megjelenítéséhez.','net.close':'Világnézet',
    'net.footer':'Nagykövetség = kétoldalú képviselet egy állam felé · Főkonzulátus = konzuli poszt egy körzet számára · Állandó misszió = képviselet egy nemzetközi szervezet felé.',
    'badge.ci':'Elefántcsontpart','ci.title':'Fedezze fel Elefántcsontpartot','ci.republic':'Elefántcsontparti Köztársaság',
    'ci.area':'Terület','ci.pop':'Népesség','ci.indep':'Függetlenség','ci.indep.val':'1960. augusztus 7.','ci.capital':'Főváros',
    'pamb.mis.p1':'Az Elefántcsontparti Köztársaság ausztriai nagykövetsége Elefántcsontpart hivatalos diplomáciai képviselete Bécsben. Biztosítja az elefántcsontparti érdekek védelmét, a kétoldalú kapcsolatok fejlesztését és állampolgárai védelmét.',
    'pamb.mis.p2':'A diplomáciai kapcsolatokról szóló 1961. évi bécsi egyezménnyel összhangban létrehozott Nagykövetség kettős küldetést tölt be: diplomáciai (az állam képviselete a fogadó országnál) és konzuli (a joghatósága alá tartozó elefántcsontparti állampolgárok segítése).',
    'pamb.mis.p3':'Területi illetékessége alapján a Nagykövetség 9 országot fed le: Ausztriát, Magyarországot, Szlovéniát, Szlovákiát, Horvátországot, Szerbiát, Romániát és Bosznia-Hercegovinát.',
    'pamb.stat.countries':'ország a Diplomáciai Körzetben','pamb.stat.conv':'Bécsi Egyezmény','pamb.stat.ci':'Elefántcsontpart','pamb.stat.host':'Fogadó ország',
    'pamb.amb.title':'Az Elefántcsontparti Köztársaság rendkívüli és meghatalmazott nagykövete Ausztriában',
    'pamb.amb.p1':'Ő Excellenciája Cissé Yacouba úr az Osztrák Köztársaságnál van akkreditálva mint az Elefántcsontparti Köztársaság rendkívüli és meghatalmazott nagykövete. Emellett Magyarországon, Szlovéniában, Szlovákiában, Horvátországban, Szerbiában, Romániában és Bosznia-Hercegovinában is akkreditálva van.',
    'pamb.amb.p2':'Hosszú, Elefántcsontpart szolgálatában eltöltött diplomáciai pályafutásával Ő Excellenciája Cissé Yacouba úr képviseli az elefántcsontparti köztársaság érdekeit, elősegíti a kétoldalú és multilaterális kapcsolatokat, és koordinálja a Nagykövetség valamennyi szolgálatát.',
    'porg.breadcrumb':'Szervezeti felépítés','porg.h1':'Szervezeti felépítés','porg.desc':'Az Elefántcsontparti Köztársaság bécsi Nagykövetségének és Állandó Képviseletének szervezeti felépítése.',
