    'pays.blurb.at':'Država gostiteljica Veleposlaništva. Dunaj gosti tudi številne mednarodne organizacije (UNIDO, IAEA, UNODC).','pays.blurb.hu':'Država članica Evropske unije, ki leži v srcu srednje Evrope.','pays.blurb.si':'Alpska država na stičišču srednje Evrope, članica Evropske unije.','pays.blurb.sk':'Mlada srednjeevropska republika, članica Evropske unije in evrskega območja.','pays.blurb.hr':'Obalna država ob Jadranskem morju, zadnja država, ki se je pridružila Evropski uniji (2013).','pays.blurb.rs':'Država kandidatka za članstvo v Evropski uniji, ki leži v srcu Balkana.','pays.blurb.ro':'Velika jugovzhodnoevropska država, članica Evropske unije od leta 2007.','pays.blurb.ba':'Balkanska država v procesu evropskega povezovanja, na stičišču kultur.','pays.blurb.md':'Vzhodnoevropska država, ki se približuje Evropski uniji.',
