    'ann.h1':'Informacije in obvestila','ann.desc':'Tukaj najdete vse uradne informacije, pomembna obvestila in sporočila Veleposlaništva Slonokoščene obale na Dunaju.',
    'ann.pinned.label':'Pripeto — Nujno','ann.pinned.title':'Izredno zaprtje — Državni praznik Slonokoščene obale','ann.pinned.desc':'Veleposlaništvo Slonokoščene obale na Dunaju bo <strong>zaprto v petek, 7. avgusta 2026</strong>, ob državnem prazniku Republike Slonokoščene obale (66. obletnica neodvisnosti). Storitve se bodo normalno nadaljevale v ponedeljek, 10. avgusta 2026, ob 09.30.','ann.pinned.date':'Objavljeno 25. maja 2026',
