    'cc.title':'Konzularna izkaznica','cc.eligibility.title':'Pogoji za upravičenost','cc.eligibility.text':'Biti državljan Slonokoščene obale, ki živi na diplomatskem območju veleposlaništva (Avstrija, Madžarska, Hrvaška, Srbija, Slovaška, Slovenija, Romunija, Bosna in Hercegovina, Moldavija).',
    'cc.docs.title':'Zahtevana dokumentacija','cc.docs.li1':'1 barvna fotografija za potni list z belo podlago','cc.docs.li2':'Fotokopija prvih 3 strani potnega lista','cc.docs.li3':'Kopija osebnega dokumenta (osebna izkaznica, potrdilo o državljanstvu)','cc.docs.li4':'Dovoljenje za prebivanje','cc.docs.li5':'Fotokopija rojstnega lista',
