    'pamb.ci.p1':'Republika Slonokoščena obala je zahodnoafriška država, na jugu mejijo na Gvinejski zaliv. Kot največje gospodarstvo Zahodnoafriške gospodarske in monetarne unije (UEMOA) je največji svetovni proizvajalec kakava.',
    'pamb.ci.p2':'Abidjan, gospodarska prestolnica, je ena najbolj dinamičnih metropol podsaharske Afrike. Yamoussoukro je politična in upravna prestolnica države.',
