    'pamb.mis.p1':'Veleposlaništvo Republike Slonokoščene obale v Avstriji je uradno diplomatsko predstavništvo Slonokoščene obale na Dunaju. Zagotavlja zaščito ivoirskih interesov, razvoj dvostranskih odnosov in zaščito svojih državljanov.',
    'pamb.mis.p2':'Ustanovljeno v skladu z Dunajsko konvencijo o diplomatskih odnosih iz leta 1961, Veleposlaništvo opravlja dvojno poslanstvo: diplomatsko (predstavljanje države pri državi gostiteljici) in konzularno (pomoč ivoirskim državljanom, ki prebivajo na njegovem območju pristojnosti).',
    'pamb.mis.p3':'V okviru svoje teritorialne pristojnosti Veleposlaništvo pokriva 9 držav: Avstrijo, Madžarsko, Slovenijo, Slovaško, Hrvaško, Srbijo, Romunijo in Bosno in Hercegovino.',
    'pamb.stat.countries':'držav v diplomatskem območju','pamb.stat.conv':'Dunajska konvencija','pamb.stat.ci':'Slonokoščena obala','pamb.stat.host':'Država gostiteljica',
