    'pamb.amb.p1':'Njegova ekscelenca gospod Cissé Yacouba je akreditiran pri Republiki Avstriji kot izredni in pooblaščeni veleposlanik Republike Slonokoščene obale. Akreditiran je tudi pri Madžarski, Sloveniji, Slovaški, Hrvaški, Srbiji, Romuniji in Bosni in Hercegovini.',
    'pamb.amb.p2':'Z dolgo diplomatsko kariero v službi Slonokoščene obale Njegova ekscelenca gospod Cissé Yacouba zastopa interese ivoirske republike, spodbuja dvostranske in večstranske odnose ter usklajuje vse službe Veleposlaništva.',
