    'dl.badge':'Úradné tlačivá','dl.h1':'Tlačivá na stiahnutie','dl.desc':'Bezplatne si stiahnite všetky úradné tlačivá Veľvyslanectva. Vytlačte si ich, vyplňte a prineste na stretnutie.',
    'dl.cat.passport':'Cestovný pas a totožnosť','dl.cat.visa':'Vízum','dl.cat.civil':'Matričné doklady','dl.cat.official':'Úradné dokumenty','dl.cat.fees':'Kancelárske poplatky','dl.btn':'Stiahnuť PDF',
    'dl.info.title':'Dôležité informácie','dl.info.text':'Tlačivá je potrebné vytlačiť, vyplniť a podpísať pred stretnutím. Všetky platby sa uskutočňujú výlučne online.',
    'dl.f01.eyebrow':'Cestovný pas','dl.f01.title':'Formulár žiadosti o cestovný pas','dl.f01.sub':'Bežný / biometrický cestovný pas v zahraničí','dl.f01.desc':'Oficiálne tlačivo Ministerstva bezpečnosti. Je potrebné ho vyplniť a podpísať pred konzulárnym stretnutím. Priložte požadované doklady.','dl.f01.size':'PDF · 68 KB',
    'dl.f02.eyebrow':'Registrácia','dl.f02.title':'Konzulárny registračný formulár','dl.f02.sub':'Zápis do registra Pobrežia Slonoviny v zahraničí','dl.f02.desc':'Povinné pre všetkých občanov Pobrežia Slonoviny s pobytom v Rakúsku. Registrácia uľahčuje prístup ku konzulárnym službám a chráni vaše práva v zahraničí.','dl.f02.size':'PDF · 124 KB',
    'dl.f03.eyebrow':'Maloletý','dl.f03.title':'Rodičovské vyhlásenie','dl.f03.sub':'Súhlas s vydaním cestovného pasu a/alebo rodného listu maloletého','dl.f03.desc':'Súhlas vydaný jedným alebo oboma rodičmi na vydanie cestovného pasu alebo rodného listu pre maloleté dieťa. Vyžaduje sa úradne overený podpis.','dl.f03.size':'PDF · 100 KB',
    'dl.f04.eyebrow':'Vízum','dl.f04.title':'Formulár žiadosti o vízum','dl.f04.sub':'Bežné, zdvorilostné alebo diplomatické vízum','dl.f04.desc':'Formulár na použitie pri každej žiadosti o vstupné vízum na Pobrežie Slonoviny. Je potrebné vyplniť všetky povinné polia. Vyžaduje sa aktuálna fotografia.','dl.f04.size':'PDF · 125 KB',
    'dl.f05.eyebrow':'Matričné doklady','dl.f05.title':'Prepis rodného listu','dl.f05.sub':'Deti narodené v zahraničí rodičom z Pobrežia Slonoviny','dl.f05.desc':'Formulár na zápis zahraničného rodného listu do matrík Pobrežia Slonoviny. Povinné pre získanie štátnej príslušnosti a cestovného pasu.','dl.f05.size':'PDF · 131 KB',
    'dl.f06.eyebrow':'Splnomocnenie','dl.f06.title':'Konzulárne splnomocnenie','dl.f06.sub':'Poverenie konať v mene tretej osoby','dl.f06.desc':'Umožňuje poverenej osobe vybavovať administratívne úkony vo vašom mene na veľvyslanectve alebo na území Pobrežia Slonoviny.','dl.f06.size':'PDF · 89 KB',
    'dl.f07.eyebrow':'Overenie','dl.f07.title':'Žiadosť o overenie','dl.f07.sub':'Overenie administratívnych alebo notárskych dokumentov','dl.f07.desc':'Formulár na overenie dokumentov z Pobrežia Slonoviny alebo zahraničných dokumentov určených na použitie na Pobreží Slonoviny alebo v tretej krajine. Vzťahuje sa na notárske, administratívne a obchodné listiny.','dl.f07.size':'PDF · 121 KB',
    'dl.f08.eyebrow':'Cestovný preukaz','dl.f08.title':'Žiadosť o cestovný preukaz','dl.f08.sub':'Dočasný cestovný doklad v núdzovej situácii','dl.f08.desc':'Dočasný cestovný doklad vydaný v prípade straty, krádeže alebo skončenia platnosti cestovného pasu. Platný na jednosmernú cestu na Pobrežie Slonoviny.','dl.f08.size':'PDF · 139 KB',
    'dl.f09.eyebrow':'Štátna príslušnosť','dl.f09.title':'Vzdanie sa štátnej príslušnosti Pobrežia Slonoviny','dl.f09.sub':'Žiadosť o potvrdenie o postúpení vzdania sa','dl.f09.desc':'Formulár, ktorý je potrebné vyplniť na začatie konania o vzdaní sa štátnej príslušnosti Pobrežia Slonoviny. Podáva sa na veľvyslanectve spolu s požadovanými dokladmi.','dl.f09.size':'PDF · 89 KB',
