    'cc.title':'Konzulárny preukaz','cc.eligibility.title':'Podmienky oprávnenosti','cc.eligibility.text':'Byť občanom Pobrežia Slonoviny žijúcim v diplomatickom obvode veľvyslanectva (Rakúsko, Maďarsko, Chorvátsko, Srbsko, Slovensko, Slovinsko, Rumunsko, Bosna a Hercegovina, Moldavsko).',
    'cc.docs.title':'Požadovaná dokumentácia','cc.docs.li1':'1 farebná fotografia veľkosti pasu s bielym pozadím','cc.docs.li2':'Fotokópia prvých 3 strán cestovného pasu','cc.docs.li3':'Kópia dokladu totožnosti (OP, osvedčenie o štátnej príslušnosti)','cc.docs.li4':'Povolenie na pobyt','cc.docs.li5':'Fotokópia rodného listu',
