    'pamb.h1':'Veľvyslanectvo Pobrežia Slonoviny','pamb.desc':'Oficiálne zastúpenie Republiky Pobrežia Slonoviny v Rakúsku so sídlom vo Viedni, ktoré zabezpečuje diplomatické vzťahy a konzulárne služby pre 9 krajín strednej Európy.',
    'pamb.mis.badge':'Naše poslanie','pamb.mis.title':'Diplomatické a konzulárne poslanie',
    'pamb.pays.badge':'Pôsobnosť','pamb.pays.title':'Diplomatický obvod','pamb.pays.sub':'Veľvyslanectvo Pobrežia Slonoviny vo Viedni pokrýva diplomatický obvod nasledujúcich 9 krajín.',
    'pamb.amb.badge':'Vedenie',
    'pamb.rel.badge':'Diplomacia','pamb.rel.title':'Vzťahy Pobrežie Slonoviny — Rakúsko',
    'pamb.ci.badge':'Pobrežie Slonoviny','pamb.ci.title':'Objavte Pobrežie Slonoviny',
    'pamb.ci.p1':'Republika Pobrežia Slonoviny je západoafrická krajina, na juhu hraničiaca s Guinejským zálivom. Ako najväčšia ekonomika Západoafrickej hospodárskej a menovej únie (UEMOA) je najväčším svetovým producentom kakaa.',
    'pamb.ci.p2':'Abidžan, ekonomické hlavné mesto, je jednou z najdynamickejších metropol subsaharskej Afriky. Yamoussoukro je politickým a administratívnym hlavným mestom krajiny.',
    'pamb.ci.stat.area':'Rozloha','pamb.ci.stat.pop':'Obyvateľstvo','pamb.ci.stat.lang':'Úradný jazyk','pamb.ci.stat.lang.val':'Francúzština','pamb.ci.stat.currency':'Mena','pamb.ci.stat.indep':'Nezávislosť','pamb.ci.stat.indep.val':'7. augusta 1960','pamb.ci.stat.capital':'Politické hlavné mesto',
    'pamb.ci.republic':'Republika Pobrežia Slonoviny',
    'pamb.org.badge':'Veľvyslanectvo','pamb.org.title':'Organizačná štruktúra',
    'pamb.org.p1':'Veľvyslanectvo a Stále zastúpenie je organizované okolo Stáleho zástupcu a špecializovaného diplomatického tímu pokrývajúceho 9 krajín strednej Európy.',
    'pamb.org.p2':'Štruktúra zahŕňa ministrov poradcov, riaditeľku UNIDO, pokladníka, poradcov, prvých tajomníkov a administratívny a technický personál.',
    'pamb.org.btn':'Zobraziť organizačnú štruktúru →',
    'pamb.net.badge':'Zahraničná sieť','pamb.net.title':'Pobrežnoslonovinská diplomatická sieť vo svete','pamb.net.desc':'Veľvyslanectvá, generálne konzuláty, stále misie a delegácie po celom svete.',
    'pamb.net.amb':'Veľvyslanectvá','pamb.net.cg':'Generálne konzuláty','pamb.net.mis':'Misie a delegácie','pamb.net.circ':'Obvody pôsobnosti','pamb.net.villes':'Mestá','pamb.net.pays':'Hostiteľské krajiny',
    'net.filter.all':'Všetky zastúpenia','net.filter.circ':'Obvody pôsobnosti','net.filter.arcs':'Spojenia z Abidžanu',
    'net.search.ph':'Hľadajte mesto, krajinu…','net.hint':'Vyberte bod na mape alebo zastúpenie zo zoznamu nižšie na zobrazenie podrobností.','net.close':'Svetový pohľad',
    'net.footer':'Veľvyslanectvo = bilaterálne zastúpenie pri štáte · Generálny konzulát = konzulárne miesto pre obvod · Stála misia = zastúpenie pri medzinárodnej organizácii.',
    'badge.ci':'Pobrežie Slonoviny','ci.title':'Objavte Pobrežie Slonoviny','ci.republic':'Republika Pobrežia Slonoviny',
    'ci.area':'Rozloha','ci.pop':'Obyvateľstvo','ci.indep':'Nezávislosť','ci.indep.val':'7. augusta 1960','ci.capital':'Hlavné mesto',
    'pamb.mis.p1':'Veľvyslanectvo Republiky Pobrežia Slonoviny v Rakúsku je oficiálnym diplomatickým zastúpením Pobrežia Slonoviny vo Viedni. Zabezpečuje obranu pobrežnoslonovinských záujmov, rozvoj bilaterálnych vzťahov a ochranu svojich občanov.',
    'pamb.mis.p2':'Zriadené v súlade s Viedenským dohovorom o diplomatických stykoch z roku 1961, Veľvyslanectvo plní dvojaké poslanie: diplomatické (zastupovanie štátu pri hostiteľskej krajine) a konzulárne (pomoc pobrežnoslonovinským občanom s pobytom v jeho obvode).',
    'pamb.mis.p3':'V rámci svojej územnej pôsobnosti Veľvyslanectvo pokrýva 9 krajín: Rakúsko, Maďarsko, Slovinsko, Slovensko, Chorvátsko, Srbsko, Rumunsko a Bosnu a Hercegovinu.',
    'pamb.stat.countries':'krajín v diplomatickom obvode','pamb.stat.conv':'Viedenský dohovor','pamb.stat.ci':'Pobrežie Slonoviny','pamb.stat.host':'Hostiteľská krajina',
    'pamb.amb.title':'Mimoriadny a splnomocnený veľvyslanec Republiky Pobrežia Slonoviny v Rakúsku',
    'pamb.amb.p1':'Jeho Excelencia pán Cissé Yacouba je akreditovaný pri Rakúskej republike ako mimoriadny a splnomocnený veľvyslanec Republiky Pobrežia Slonoviny. Je tiež akreditovaný pri Maďarsku, Slovinsku, Slovensku, Chorvátsku, Srbsku, Rumunsku a Bosne a Hercegovine.',
    'pamb.amb.p2':'S bohatou diplomatickou kariérou v službách Pobrežia Slonoviny Jeho Excelencia pán Cissé Yacouba zastupuje záujmy pobrežnoslonovinskej republiky, podporuje bilaterálne a multilaterálne vzťahy a koordinuje všetky služby Veľvyslanectva.',
    'porg.breadcrumb':'Organizačná štruktúra','porg.h1':'Organizačná štruktúra','porg.desc':'Organizačná štruktúra Veľvyslanectva a Stáleho zastúpenia Pobrežia Slonoviny vo Viedni.',
    'porg.motto':'REPUBLIKA POBREŽIA SLONOVINY — JEDNOTA · DISCIPLÍNA · PRÁCA',
